/*selectBuyerMpSoUniformChoicePopList*/ SELECT A.BUYER_ITEM_NO, B.DESCRIPTION_LOC, B.SPECIFICATION, A.UNIT_MEASURE, A.BUYER, A.BELOW_COMORG_CODE, A.CONTRACT_NO, A.CONTRACT_SEQ FROM ICOMCQDT A, ICOMBYIT B, ICOMCOD2 C WHERE 1=1 AND A.BUYER = B.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.STATUS IN ('C', 'R') AND B.STATUS IN ('C', 'R') AND B.PRODUCT_CLOSE_FLAG <> 'Y' AND A.BELOW_COMORG_CODE = C.COMPANY_CODE AND A.BUYER_ITEM_NO = C.CODE AND A.AGENT = C.TEXT1 AND C.TYPE = 'ST00' AND C.FLAG = 'Y' AND C.COMPANY_CODE = #{com_code}
AND C.CODE LIKE '%' || #{st_buyer_item_no} || '%'
AND B.DESCRIPTION_LOC LIKE '%' || #{st_description} || '%'
AND B.SPECIFICATION LIKE '%' || #{st_specification} || '%'
